package it.andreademartini.trading.paper.patternv1;
import static it.andreademartini.trading.paper.patternv1.PatternPaperModel.*;
import static it.andreademartini.trading.paper.patternv1.PatternPaperTestSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import it.andreademartini.trading.config.TradingMode;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;

class PatternPaperServiceTest {
    @Test void verifiedPaperStartsWithoutChangingFrozenConfiguration(){var h=new Harness();h.start();assertEquals(Mode.PAPER_AUTO,h.session.mode);assertEquals(13,h.session.frozen.configuration().global().maxHoldingBars());assertFalse(h.session.frozen.configuration().global().useLeverage());verify(h.broker,never()).place(any());}
    @Test void liveModeIsRejectedEvenWithAClaimedPaperAccount(){var h=new Harness();h.properties.setMode(TradingMode.LIVE);h.start();assertEquals(Mode.ERROR,h.session.mode);assertTrue(h.session.reason.contains("PAPER_ONLY"));verify(h.broker,never()).place(any());}
    @Test void accountPrefixAndPaperPortCannotVerifyIdentity(){var h=new Harness();when(h.broker.connection()).thenReturn(connection(false,true));h.start();assertEquals(Mode.ERROR,h.session.mode);assertTrue(h.session.reason.contains("PAPER_IDENTITY"));verify(h.broker,never()).place(any());}
    @Test void readOnlyApiCannotStart(){var h=new Harness();when(h.broker.connection()).thenReturn(connection(true,false));h.start();assertEquals(Mode.ERROR,h.session.mode);assertTrue(h.session.reason.contains("WRITE_CAPABILITY"));verify(h.broker,never()).place(any());}
    @Test void missingLimitsCannotBeSilentlyDefaulted(){var h=new Harness();h.session.limits=Limits.unset();h.start();assertEquals(Mode.ERROR,h.session.mode);assertTrue(h.session.reason.contains("OPERATIONAL_LIMITS"));}
    @Test void incompleteReconciliationCannotStart(){var h=new Harness();h.snapshot=new BrokerSnapshot(1,Instant.now(),List.of(),List.of(),List.of(),List.of(),bd(1000000),false,"Timeout");h.start();assertEquals(Mode.ERROR,h.session.mode);verify(h.broker,never()).place(any());}
    @Test void otherBrokerPositionCannotBeAttributedToV1(){var h=new Harness();h.snapshot=new BrokerSnapshot(1,Instant.now(),List.of(new BrokerPosition(ACCOUNT,"AAPL",bd(5),bd(100))),List.of(),List.of(),List.of(),bd(1000000),true,"OK");h.start();assertEquals(Mode.ERROR,h.session.mode);assertNull(h.session.lastReconciliation);verify(h.broker,never()).place(any());}
    @Test void longEntryHasDurableThreeOrderBracketAndThirtyPercentSizing(){var h=new Harness();h.enter();assertEquals(3,h.session.orders.size());var entry=h.session.orders.stream().filter(o->o.role==Role.ENTRY).findFirst().orElseThrow();assertTrue(entry.quantity<=30);assertTrue(entry.quantity>0);assertTrue(BigDecimal.valueOf(entry.quantity).multiply(bd(100)).compareTo(bd(3000))<=0);assertTrue(h.session.signals.getFirst().expectedEntry.subtract(h.session.signals.getFirst().expectedStop).abs().multiply(bd(entry.quantity)).compareTo(bd(200))<=0);verify(h.broker,times(3)).place(any());assertEquals("SUBMITTED",h.session.signals.getFirst().status);assertFalse(h.session.orders.getFirst().transmit);assertTrue(h.session.orders.getLast().transmit);}
    @Test void stopPreventsNewEntriesAndRefreshNeverSubmits(){var h=new Harness();h.start();h.session.signals.add(signal("AAPL"));h.service.stop(UUID.randomUUID().toString());h.service.refresh();h.service.tick(Instant.now());assertEquals(Mode.STOPPING,h.session.mode);verify(h.broker,never()).place(any());verify(h.broker,never()).cancelVerifiedUnfilledEntry(any());}
    @Test void globalKillAlsoBlocksDedicatedV1(){var h=new Harness();h.kill.activate("test");h.start();assertEquals(Mode.ERROR,h.session.mode);verify(h.broker,never()).place(any());}
    @Test void killIsPersistentAndCannotResetWithoutExplicitConfirmation(){var h=new Harness();h.start();h.service.kill(UUID.randomUUID().toString(),"ATTIVA KILL SWITCH");assertTrue(h.session.killSwitch);assertEquals(Mode.KILL_SWITCH,h.session.mode);h.session=PatternPaperStore.read(PatternPaperStore.json(h.session),Session.class);h.service.recover();assertEquals(Mode.KILL_SWITCH,h.session.mode);assertThrows(IllegalArgumentException.class,()->h.service.reset(UUID.randomUUID().toString(),""));h.service.reset(UUID.randomUUID().toString(),"RESET KILL SWITCH");assertEquals(Mode.DISABLED,h.session.mode);assertFalse(h.session.killSwitch);}
    @Test void duplicateSignalCannotTransmitTwice(){var h=new Harness();h.enter();h.service.tick(Instant.now());verify(h.broker,times(3)).place(any());assertEquals(3,h.session.orders.size());}
    @Test void uncertainSubmissionIsNotRetriedAfterRestart(){var h=new Harness();doThrow(new IllegalStateException("network uncertain")).when(h.broker).place(any());h.enter();assertEquals("UNCERTAIN",h.session.signals.getFirst().status);assertEquals(Mode.ERROR,h.session.mode);h.session=PatternPaperStore.read(PatternPaperStore.json(h.session),Session.class);h.service.recover();h.service.tick(Instant.now());verify(h.broker,times(1)).place(any());}
    @Test void restartSuspendsAutoUntilReconciliation(){var h=new Harness();h.start();h.session=PatternPaperStore.read(PatternPaperStore.json(h.session),Session.class);h.service.recover();assertEquals(Mode.STOPPING,h.session.mode);assertNull(h.session.lastReconciliation);assertTrue(h.session.resumeRequested);verify(h.broker,never()).place(any());}
    @Test void staleQuoteCannotOpenPosition(){var h=new Harness();h.start();h.session.signals.add(signal("AAPL"));when(h.broker.quote(anyString())).thenReturn(new Quote(bd(100),bd(100),bd(100),bd(100),Instant.now().minusSeconds(60),LocalDate.now(ZoneId.of("America/New_York")),true,null,null));h.service.tick(Instant.now());assertEquals("SKIPPED",h.session.signals.getFirst().status);verify(h.broker,never()).place(any());}
    @Test void missingOpenCannotBeReplacedWithCloseOrLast(){var h=new Harness();h.start();h.session.signals.add(signal("AAPL"));when(h.broker.quote(anyString())).thenReturn(new Quote(null,bd(100),bd(100),bd(100),Instant.now(),LocalDate.now(ZoneId.of("America/New_York")),true,null,null));h.service.tick(Instant.now());assertEquals("SKIPPED",h.session.signals.getFirst().status);assertTrue(h.session.signals.getFirst().reason.contains("OPEN"));verify(h.broker,never()).place(any());}
    @Test void unavailableDataCannotGenerateInventedDailySignals(){var h=new Harness();h.service.shadow(UUID.randomUUID().toString());var future=h.now.plusSeconds(3661);h.service.tick(future);assertEquals(Mode.ERROR,h.session.mode);assertTrue(h.session.reason.contains("DAILY"));assertTrue(h.session.signals.isEmpty());verify(h.broker,never()).place(any());}
    @Test void closedDailySignalExcludesFutureBarAndIsGeneratedOnce(){var h=new Harness();h.service.shadow(UUID.randomUUID().toString());var day=LocalDate.now(ZoneId.of("America/New_York"));
        when(h.broker.dailyBars(anyString())).thenAnswer(i->{String symbol=i.getArgument(0);return List.of(bar(symbol,day.minusDays(1),0,100,101,98,99),bar(symbol,day,1,98.5,101,98.2,100.5),bar(symbol,day.plusDays(1),2,1,200,1,100));});
        var afterClose=h.now.plusSeconds(3661);h.service.tick(afterClose);var count=h.session.signals.size();assertTrue(count>0);h.service.tick(afterClose.plusSeconds(1));assertEquals(count,h.session.signals.size());assertTrue(h.session.signals.stream().allMatch(s->s.signal.detection().signalDate().equals(day)&&s.mode.equals("SHADOW")));verify(h.broker,never()).place(any());}
    @Test void controlsAreIdempotent(){var h=new Harness();var command=UUID.randomUUID().toString();h.service.stop(command);long generation=h.session.generation;h.service.stop(command);assertEquals(generation,h.session.generation);assertEquals(1,h.events.stream().filter(e->e.type().equals("STOPPING")).count());}
    @Test void aggregateExposureCannotExceedUnleveredEquity(){var h=new Harness();assertThrows(IllegalArgumentException.class,()->h.service.configure(new Limits(bd(500),bd(30),10,20,bd(101)),UUID.randomUUID().toString()));}
    @Test void partialFillProtectionMustMatchActuallyFilledQuantity(){var h=new Harness();h.enter();var fill=new ExecutionRecord("partial",null,100,1000,ACCOUNT,"AAPL","BUY",bd(5),bd(100),Instant.now(),null);
        var orders=h.brokerOrders().stream().map(o->new BrokerOrder(o.id(),o.permId(),o.parentId(),o.account(),o.symbol(),o.clientOrderId(),o.action(),o.type(),o.quantity(),o.id()==100?bd(5):bd(0),"Submitted",o.stop(),o.limit(),o.ocaGroup())).toList();
        h.snapshot=new BrokerSnapshot(1,Instant.now(),List.of(new BrokerPosition(ACCOUNT,"AAPL",bd(5),bd(100))),orders,List.of(fill),List.of(),bd(1000000),true,"OK");h.service.refresh();
        assertEquals(Mode.ERROR,h.session.mode);assertTrue(h.session.reason.contains("Protezione"));var t=h.session.trades.getFirst();assertFalse(PatternPaperService.protectedTrade(t,orders,ACCOUNT));
        var repaired=orders.stream().filter(o->o.id()!=100).map(o->new BrokerOrder(o.id(),o.permId(),0,o.account(),o.symbol(),o.clientOrderId(),o.action(),o.type(),bd(5),bd(0),"Submitted",o.stop(),o.limit(),o.ocaGroup())).toList();
        assertTrue(PatternPaperService.protectedTrade(t,repaired,ACCOUNT));verify(h.broker,times(3)).place(any());
    }
    @Test void timeoutUsesThirteenSessionsAndRetainsStops(){var h=new Harness();h.enter();var fill=new ExecutionRecord("entry",null,100,1000,ACCOUNT,"AAPL","BUY",bd(h.session.orders.getFirst().quantity),bd(100),Instant.now().minus(Duration.ofDays(12)),null);
        var orders=h.brokerOrders();h.snapshot=new BrokerSnapshot(1,Instant.now(),List.of(new BrokerPosition(ACCOUNT,"AAPL",fill.quantity(),bd(100))),orders,List.of(fill),List.of(),bd(1000000),true,"OK");h.service.refresh();
        when(h.broker.timeout(any(),anyLong(),anyString(),anyString())).thenAnswer(i->{var t=(Trade)i.getArgument(0);long q=i.getArgument(1);var c=new com.ib.client.Contract();c.symbol(t.symbol);var o=new com.ib.client.Order();o.orderId(999);o.account(ACCOUNT);o.orderRef("PV1:"+t.signalId+":TIMEOUT");o.action("SELL");o.orderType("MOC");o.ocaGroup("PV1:"+t.signalId);o.totalQuantity(com.ib.client.Decimal.get(q));o.transmit(true);
            return new it.andreademartini.trading.orders.IbkrOrderCommand(999,null,t.signalId,"TIMEOUT",t.symbol,it.andreademartini.trading.orders.OrderSide.SELL,it.andreademartini.trading.orders.PaperOrderType.MARKET,null,null,q,100d,null,null,null,c,o);});
        h.service.tick(h.now.plusSeconds(1801));assertEquals(13,h.session.trades.getFirst().holdingBars);assertTrue(h.session.trades.getFirst().timeoutSubmitted);verify(h.broker,times(1)).timeout(any(),anyLong(),anyString(),anyString());verify(h.broker,never()).cancelVerifiedUnfilledEntry(any());assertEquals(1,h.session.orders.stream().filter(o->o.role==Role.TIMEOUT).count());
    }
    @Test void disconnectCannotResumeFromAnOldSnapshot(){var h=new Harness();h.start();when(h.broker.connection()).thenReturn(new Connection(false,"127.0.0.1",4002,ACCOUNT,List.of(),false,false,false,"disconnected",null,null,2));h.service.tick(Instant.now());assertEquals(Mode.ERROR,h.session.mode);assertNull(h.session.lastReconciliation);verify(h.broker,never()).place(any());}
}
